files.rank_candidates/score_candidates.ts:
/** Attach the exact quality/cost score to every candidate. */
export default function score_candidates(items: Candidate[]): Ranked[] {
  return items.map(x => ({ ...x, score: x.quality * 100 - x.cost }))
}

files.rank_candidates/sort_ranked.ts:
/** Sort ranked candidates by score descending and id ascending. */
export default function sort_ranked(items: Ranked[]): Ranked[] {
  return items.slice().sort((a, b) => b.score - a.score || a.id.localeCompare(b.id))
}

files.rank_candidates/take_ranked.ts:
/** Take the requested prefix of a ranked list. */
export default function take_ranked(items: Ranked[], k: number): Ranked[] {
  return items.slice(0, k)
}

files.account_leaderboard/active_only.ts:
/** Keep only active transactions. */
export default function active_only(items: Transaction[]): Transaction[] {
  return items.filter(x => x.active)
}

files.account_leaderboard/rank_accounts.ts:
/** Pair accounts with totals and sort the leaderboard. */
export default function rank_accounts(accounts: string[], totals: number[]): Summary[] {
  return accounts.map((account, i) => ({ account, total: totals[i] })).sort((a, b) => b.total - a.total || a.account.localeCompare(b.account))
}

